import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";

// 1. API_BASE definition
// Using a direct constant URL to avoid "import.meta.env" compilation warnings, 
// defaulting to the localhost backend as intended.
const API_BASE = "http://localhost:8000/api";

const HomePage = () => {
  // 2. State definitions
  const [feedbacks, setFeedbacks] = useState([]);
  const [name, setName] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  // 3. useEffect to fetch data on mount
  useEffect(() => {
    fetchFeedbacks();
    // The dependency array is empty because we only want to fetch once on mount.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 4. Handler functions
  const fetchFeedbacks = async () => {
    setLoading(true);
    setError("");
    try {
      // Fetching all existing feedback posts
      const res = await fetch(`${API_BASE}/feedbacks/`);
      if (!res.ok) throw new Error("Failed to load feedbacks");
      const data = await res.json();
      setFeedbacks(data);
    } catch (err) {
      setError("Could not load feedbacks. Try again later.");
      console.error("Fetch Feedbacks Error:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!message.trim()) return setError("Message cannot be empty.");
    setSubmitting(true);
    setError("");
    try {
      // Posting new feedback
      const res = await fetch(`${API_BASE}/feedbacks/`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ name: name.trim(), message: message.trim() }),
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(text || "Failed to submit feedback");
      }
      const newFeedback = await res.json();
      // Prepend the new feedback to the list so it appears instantly at the top
      setFeedbacks((prev) => [newFeedback, ...prev]);
      setName("");
      setMessage("");
    } catch (err) {
      console.error("Submit Feedback Error:", err);
      setError("Failed to submit. Please ensure your message is appropriate.");
    } finally {
      setSubmitting(false);
    }
  };

  // 5. JSX structure
  return (
    <div className="min-h-screen flex flex-col">
      {/* Hero Section */}
      <header className="bg-gradient-to-br from-indigo-400 to-purple-600 text-white p-8 flex flex-col md:flex-row items-center min-h-[60vh]">
        <div className="flex-1 max-w-xl">
          <h1 className="text-5xl font-bold mb-4 leading-tight">
            Welcome to Pet Rescue Platform
          </h1>
          <p className="text-lg mb-8 opacity-90 leading-relaxed">
            Help reunite lost pets with their families and find loving homes for
            pets in need.
          </p>
          <div className="flex flex-wrap gap-4">
            <Link
              to="/login"
              className="inline-block px-6 py-3 rounded-lg bg-green-600 text-white font-medium hover:bg-green-700 hover:-translate-y-0.5 transition"
            >
              Get Started
            </Link>
            <Link
              to="/register"
              className="inline-block px-6 py-3 rounded-lg border-2 border-white text-white font-medium hover:bg-white hover:text-indigo-500 transition"
            >
              Join Our Community
            </Link>
          </div>
        </div>

        <div className="flex-1 flex justify-center items-center mt-8 md:mt-0">
          <div className="w-72 h-72 bg-white/10 rounded-full flex items-center justify-center">
            <span className="material-icons text-[8rem] opacity-80">pets</span>
          </div>
        </div>
      </header>

      {/* Features Section and Feedback Section */}
      <section className="py-16 px-4 bg-white">
        <div className="max-w-6xl mx-auto">
          <h2 className="text-4xl font-bold text-center text-gray-800 mb-12">
            How We Help
          </h2>
          
          {/* Feature Cards Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 mb-16"> 
            
            {/* Card 1: Report Lost Pets */}
            <div className="bg-gray-100 p-8 rounded-xl text-center shadow-md hover:-translate-y-1 transition">
              <div className="w-20 h-20 bg-indigo-500 rounded-full flex items-center justify-center mx-auto mb-4 text-white text-3xl">
                <span className="material-icons">search</span>
              </div>
              <h3 className="text-xl font-semibold mb-2 text-gray-800">
                Report Lost Pets
              </h3>
              <p className="text-gray-600 leading-relaxed">
                Quickly report lost pets with detailed descriptions and photos to
                help find them.
              </p>
            </div>

            {/* Card 2: Search Found Pets */}
            <div className="bg-gray-100 p-8 rounded-xl text-center shadow-md hover:-translate-y-1 transition">
              <div className="w-20 h-20 bg-indigo-500 rounded-full flex items-center justify-center mx-auto mb-4 text-white text-3xl">
                <span className="material-icons">visibility</span>
              </div>
              <h3 className="text-xl font-semibold mb-2 text-gray-800">
                Search Found Pets
              </h3>
              <p className="text-gray-600 leading-relaxed">
                Browse through pets that have been found and help identify their
                owners.
              </p>
            </div>

            {/* Card 3: Adoption Services */}
            <div className="bg-gray-100 p-8 rounded-xl text-center shadow-md hover:-translate-y-1 transition">
              <div className="w-20 h-20 bg-indigo-500 rounded-full flex items-center justify-center mx-auto mb-4 text-white text-3xl">
                <span className="material-icons">favorite</span>
              </div>
              <h3 className="text-xl font-semibold mb-2 text-gray-800">
                Adoption Services
              </h3>
              <p className="text-gray-600 leading-relaxed">
                Find loving homes for pets in need through our adoption
                platform.
              </p>
            </div>
          </div>
          
          {/* Community Feedback Area (NEW) */}
          <div className="max-w-4xl mx-auto">
            <h3 className="text-2xl font-bold mb-4 text-gray-800">Community Feedback</h3>

            {/* Feedback Form */}
            <form onSubmit={handleSubmit} className="bg-gray-50 p-6 rounded-lg shadow mb-8">
              {error && (
                <div className="text-sm text-red-600 mb-3 p-2 border border-red-300 bg-red-50 rounded">{error}</div>
              )}
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-4">
                <input
                  className="sm:col-span-1 p-3 rounded border focus:ring-indigo-500 focus:border-indigo-500"
                  placeholder="Your name (optional)"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  disabled={submitting}
                />
                <textarea
                  className="sm:col-span-2 p-3 rounded border focus:ring-indigo-500 focus:border-indigo-500 resize-none"
                  placeholder="Share your thoughts or success stories..."
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                  rows="3"
                  required
                  disabled={submitting}
                />
              </div>
              <div className="flex items-center gap-4">
                <button
                  type="submit"
                  className="px-6 py-2 bg-indigo-600 text-white rounded-lg font-medium hover:bg-indigo-700 transition duration-150 disabled:opacity-50"
                  disabled={submitting || !message.trim()}
                >
                  {submitting ? "Sending..." : "Send Feedback"}
                </button>
                <button
                  type="button"
                  className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-100 transition duration-150"
                  onClick={() => { setName(""); setMessage(""); setError(""); }}
                  disabled={submitting}
                >
                  Clear
                </button>
              </div>
            </form>

            {/* Feedback List */}
            <div>
              <h4 className="text-xl font-semibold mb-4 text-gray-700 border-b pb-2">Recent Community Posts</h4>
              {loading ? (
                <div className="text-center py-8 text-indigo-600">
                    <span className="animate-spin material-icons mr-2">refresh</span> Loading feedback...
                </div>
              ) : feedbacks.length === 0 ? (
                <div className="text-center py-8 text-gray-600 bg-gray-50 rounded-lg border">No feedback yet — be the first to share your experience!</div>
              ) : (
                <ul className="space-y-4">
                  {feedbacks.map((f) => (
                    <li key={f.id} className="bg-white p-5 rounded-xl shadow-lg border border-gray-100">
                      <div className="flex justify-between items-start gap-2">
                        <div>
                          <div className="font-bold text-lg text-gray-900">{f.name || "Anonymous User"}</div>
                          <div className="text-xs text-gray-500 mt-0.5">Posted on {new Date(f.created_at).toLocaleString()}</div>
                        </div>
                      </div>
                      <p className="mt-4 text-gray-800 whitespace-pre-line">{f.message}</p>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>

        </div>
      </section>

      {/* Footer */}
      <footer className="bg-gray-800 text-white py-8 text-center">
        <div className="max-w-6xl mx-auto">
          <p className="opacity-80 m-0">
            &copy; 2025 Pet Rescue Platform. Helping pets find their way home.
          </p>
        </div>
      </footer>
    </div>
  );
};

export default HomePage;
